export const CONSTITUTION_ARTICLES = [
  // Part I: Introductory
  { part: 'I', part_title: 'Introductory', chapter: '', chapter_title: '', article: '1', title: 'The Republic and its territory', content: 'Pakistan shall be a Federal Republic to be known as the Islamic Republic of Pakistan, hereinafter called Pakistan.\n(2) The territories of Pakistan shall comprise -\n(a) the territories of the Provinces of Balochistan, Khyber Pakhtunkhwa, the Punjab and Sindh;\n(b) the Islamabad Capital Territory, hereinafter referred to as the Federal Capital;\n(c) such States and territories as are or may be included in Pakistan, whether by accession or otherwise.\n(3) The Majlis-e-Shoora (Parliament) may by law admit into Pakistan new States or territories, or create new Provinces, and may, with the consent of the governments of the Provinces concerned, alter the boundaries or names of the Provinces.', category: 'Fundamental' },
  { part: 'I', part_title: 'Introductory', chapter: '', chapter_title: '', article: '2', title: 'Islam to be the state religion', content: 'Islam shall be the State religion of Pakistan.', category: 'Islamic' },
  { part: 'I', part_title: 'Introductory', chapter: '', chapter_title: '', article: '2A', title: 'The Objectives Resolution', content: 'The principles and provisions set out in the Objectives Resolution reproduced in the Annex to the Constitution shall form part of the Constitution.', category: 'Islamic' },
  { part: 'I', part_title: 'Introductory', chapter: '', chapter_title: '', article: '3', title: 'Elimination of exploitation', content: 'The State shall ensure the elimination of all forms of exploitation and the gradual fulfillment of the fundamental principle of social justice.', category: 'Fundamental' },
  { part: 'I', part_title: 'Introductory', chapter: '', chapter_title: '', article: '4', title: 'Right of individuals to be dealt with in accordance with law', content: '(1) To enjoy the protection of law and to be treated in accordance with law is the inalienable right of every citizen, wherever he may be, and of every other person for the time being within Pakistan.\n(2) In particular -\n(a) no action detrimental to the life, liberty, body, reputation or property of any person shall be taken except in accordance with law;\n(b) no person shall be prevented from or be hindered in doing any act which is permitted by law; and\n(c) no person shall be compelled to do any act which the law does not require him to do.', category: 'Fundamental' },
  { part: 'I', part_title: 'Introductory', chapter: '', chapter_title: '', article: '5', title: 'Loyalty to the State and obedience to law', content: '(1) Loyalty to the State is the basic duty of every citizen.\n(2) Obedience to law is the inviolable obligation of every citizen, wherever he may be, and of every other person for the time being within Pakistan.', category: 'Fundamental' },
  { part: 'I', part_title: 'Introductory', chapter: '', chapter_title: '', article: '6', title: 'High treason', content: '(1) Any person who abrogates or subverts or suspends or holds in abeyance, or attempts or conspires to abrogate or subvert or suspend or hold in abeyance, the Constitution by use of force or show of force or by any other unconstitutional means shall be guilty of high treason.\n(2) Any person aiding or abetting the acts mentioned in clause (1) shall likewise be guilty of high treason.\n(3) An act of high treason shall not be validated by any court.', category: 'Criminal' },

  // Part II: Fundamental Rights and Principles of Policy
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '7', title: 'Definition of the State', content: 'In this Part, "the State" means the Federal Government, Majlis-e-Shoora (Parliament), a Provincial Government, a Provincial Assembly, and such local authorities in Pakistan as may be determined by or under law.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '8', title: 'Laws inconsistent with or in derogation of Fundamental Rights to be void', content: '(1) Any law, or any custom or usage having the force of law, in so far as it is inconsistent with, or derogates from, any Fundamental Right conferred by Chapter I of Part II, shall be void.\n(2) The State shall not make any law which takes away or abridges the Fundamental Rights conferred by this Chapter; and any law made in contravention of this clause shall, to the extent of such contravention, be void.\n(3) The provisions of this Article shall not apply to any law relating to members of the Armed Forces, or of the police or other forces charged with the maintenance of public order, for the purpose of ensuring the proper discharge of their duties or the maintenance of discipline among them.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '9', title: 'Security of person', content: 'No person shall be deprived of life or liberty save in accordance with law.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '10', title: 'Safeguards as to arrest and detention', content: '(1) No person who is arrested shall be detained in custody without being informed, as soon as may be, of the grounds for such arrest, nor shall he be denied the right to consult and be defended by a legal practitioner of his choice.\n(2) Every person who is arrested and detained in custody shall be produced before a magistrate within a period of twenty-four hours of such arrest, and shall not be detained in custody beyond the said period without the authority of a magistrate.\n(3) Nothing in clauses (1) and (2) shall apply to any person who is arrested or detained under any law providing for preventive detention.\n(4) No law providing for preventive detention shall authorise the detention of a person for a period exceeding one month unless the appropriate Review Board has, after affording him an opportunity of being heard, reported before the expiry of the said period that there is, in its opinion, sufficient cause for such detention.\n(5) When any person is detained in pursuance of an order made under any law providing for preventive detention, the authority making the order shall, as soon as may be, but not later than fifteen days from the date of such detention, communicate to him the grounds on which the order has been made, and shall afford him the earliest opportunity of making a representation against the order.\n(6) The authority making the order shall, within fifteen days, refer the case to the appropriate Review Board for its review.\n(7) A Review Board shall consist of a Chairman who is a Judge of a High Court and two other members, one of whom shall be a person from the Armed Forces.\n(8) Nothing in this Article shall apply to any enemy alien.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '10A', title: 'Right to fair trial', content: 'For the determination of his civil rights and obligations or in any criminal charge against him a person shall be entitled to a fair trial and due process.', category: 'Criminal' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '11', title: 'Slavery, forced labour, etc. prohibited', content: '(1) Slavery is non-existent and forbidden and no law shall permit or facilitate its introduction into Pakistan in any form.\n(2) All forms of forced labour and traffic in human beings are prohibited.\n(3) No child below the age of fourteen years shall be engaged in any factory or mine or any other hazardous employment.\n(4) Nothing in this Article shall be deemed to require compulsory service by any person undergoing punishment for an offence against any law.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '12', title: 'Protection against retrospective punishment', content: '(1) No law shall authorize the punishment of a person -\n(a) for an act or omission that was not punishable by law at the time of the act or omission; or\n(b) for an offence with a punishment greater than that which was applicable at the time of the offence.\n(2) Nothing in this Article shall apply to any law making acts of abrogation or subversion of the Constitution an offence.', category: 'Criminal' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '13', title: 'Protection against double punishment and self-incrimination', content: 'No person -\n(a) shall be prosecuted or punished for the same offence more than once; or\n(b) shall, when accused of an offence, be compelled to be a witness against himself.', category: 'Criminal' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '14', title: 'Inviolability of dignity of man, etc.', content: '(1) The dignity of a person and the privacy of the home shall be inviolable.\n(2) No person shall be subjected to torture for the purpose of extracting evidence.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '15', title: 'Freedom of movement', content: 'Every citizen shall have the right to remain in, and, subject to any reasonable restrictions imposed by law in the public interest, enter and move throughout Pakistan and to reside and settle in any part thereof.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '16', title: 'Freedom of assembly', content: 'Every citizen shall have the right to assemble peacefully and without arms, subject to any reasonable restrictions imposed by law in the interest of public order.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '17', title: 'Freedom of association', content: '(1) Every citizen shall have the right to form associations or unions, subject to any reasonable restrictions imposed by law in the interest of sovereignty or integrity of Pakistan, public order or morality.\n(2) Every citizen, not being in the service of Pakistan, shall have the right to form or be a member of a political party.\n(3) Every political party shall account for the sources of its funds in accordance with law.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '18', title: 'Freedom of trade, business or profession', content: 'Subject to such qualifications, if any, as may be prescribed by law, every citizen shall have the right to enter upon any lawful profession or occupation, and to conduct any lawful trade or business.', category: 'Corporate' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '19', title: 'Freedom of speech, etc.', content: 'Every citizen shall have the right to freedom of speech and expression, and there shall be freedom of the press, subject to any reasonable restrictions imposed by law in the interest of the glory of Islam or the integrity, security or defence of Pakistan or any part thereof, friendly relations with foreign States, public order, decency or morality, or in relation to contempt of court, commission of or incitement to an offence.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '19A', title: 'Right to information', content: 'Every citizen shall have the right to have access to information in all matters of public importance subject to regulation and reasonable restrictions imposed by law.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '20', title: 'Freedom to profess religion and to manage religious institutions', content: 'Subject to law, public order and morality -\n(a) every citizen shall have the right to profess, practice and propagate his religion; and\n(b) every religious denomination and every sect thereof shall have the right to establish, maintain and manage its religious institutions.', category: 'Islamic' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '21', title: 'Safeguard against taxation for purposes of any particular religion', content: 'No person shall be compelled to pay any special tax the proceeds of which are to be spent on the propagation or maintenance of any religion other than his own.', category: 'Islamic' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '22', title: 'Safeguards as to educational institutions in respect of religion, etc.', content: '(1) No person attending any educational institution shall be required to receive religious instruction, or take part in any religious ceremony, or attend religious worship, if such instruction, ceremony or worship relates to a religion other than his own.\n(2) In respect of any religious institution, there shall be no discrimination against any community in the granting of exemption or concession in relation to taxation.\n(3) Subject to law, an educational institution receiving aid from public revenues shall not be denied the right to conduct religious instruction for those students who consent to receive it.\n(4) Nothing in this Article shall prevent any public authority from making provision for the advancement of any socially or educationally backward class of citizens.', category: 'Islamic' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '23', title: 'Provision as to property', content: 'Every citizen shall have the right to acquire, hold and dispose of property in any part of Pakistan, subject to the Constitution and any reasonable restrictions imposed by law in the public interest.', category: 'Property' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '24', title: 'Protection of property rights', content: '(1) No person shall be compulsorily deprived of his property save in accordance with law.\n(2) No property shall be compulsorily acquired or taken possession of save for a public purpose, and save by the authority of law which provides for compensation therefor and either fixes the amount of compensation or specifies the principles on which and the manner in which compensation is to be determined and given.\n(3) Nothing in this Article shall affect the validity of any law permitting the compulsory acquisition of any property by the Government for a public purpose.\n(4) The adequacy of compensation shall not be called in question by any court.', category: 'Property' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '25', title: 'Equality of citizens', content: '(1) All citizens are equal before law and are entitled to equal protection of law.\n(2) There shall be no discrimination on the basis of sex.\n(3) Nothing in this Article shall prevent the State from making any special provision for the protection of women and children.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '26', title: 'Non-discrimination in respect of access to public places', content: '(1) In respect of access to places of public entertainment or resort not intended for religious purposes only, there shall be no discrimination against any citizen on the ground only of race, religion, caste, sex, residence or place of birth.\n(2) Nothing in this Article shall prevent the State from making any special provision for women and children.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '27', title: 'Safeguard against discrimination in services', content: '(1) No citizen otherwise qualified for appointment in the service of Pakistan shall be discriminated against in respect of any such appointment on the ground only of race, religion, caste, sex, residence or place of birth.\n(2) Nothing in this clause shall prevent the State from reserving posts for persons belonging to any class or area for a specified period.', category: 'Service' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '1', chapter_title: 'Fundamental Rights', article: '28', title: 'Preservation of language, script and culture', content: 'Subject to Article 251, any section of citizens having a distinct language, script or culture shall have the right to preserve and promote the same and, subject to law, establish institutions for that purpose.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '29', title: 'Principles of Policy', content: '(1) The Principles set out in this Chapter shall be known as the Principles of Policy, and it shall be the responsibility of each organ and authority of the State, and each person performing functions on behalf of the State, to act in accordance with those Principles in so far as they relate to the functions of the organ or authority.\n(2) The validity of an action or of a law shall not be called in question on the ground that it is not in accordance with the Principles of Policy, and no action shall lie against the State or any organ or authority of the State for the reason that it has not acted in accordance with the Principles of Policy.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '30', title: 'Application of Principles', content: 'The responsibility of deciding whether any action or law is in accordance with the Principles of Policy shall be that of the Majlis-e-Shoora (Parliament) and the Provincial Assemblies.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '31', title: 'Islamic way of life', content: '(1) Steps shall be taken to enable the Muslims of Pakistan, individually and collectively, to order their lives in accordance with the fundamental principles and basic concepts of Islam and to provide facilities whereby they may be enabled to understand the meaning of life according to the Holy Quran and Sunnah.\n(2) The State shall endeavor, as respects the Muslims of Pakistan, to make the teaching of the Holy Quran and Islamiat compulsory, to encourage and facilitate the learning of Arabic language and to secure correct and exact printing and publication of the Holy Quran.', category: 'Islamic' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '32', title: 'Promotion of local government institutions', content: 'The State shall encourage local Government institutions composed of elected representatives of the areas concerned and in such institutions special representation shall be given to peasants, workers and women.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '33', title: 'Parochial and other prejudices', content: 'The State shall discourage parochial, racial, tribal, sectarian and provincial prejudices among the citizens.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '34', title: 'Full participation of women in national life', content: 'Steps shall be taken to ensure full participation of women in all spheres of national life.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '35', title: 'Protection of family, etc.', content: 'The State shall protect the marriage, the family, the mother and the child.', category: 'Family' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '36', title: 'Protection of minorities', content: 'The State shall safeguard the legitimate rights and interests of minorities, including their due representation in the Federal and Provincial services.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '37', title: 'Promotion of social justice and eradication of social evils', content: 'The State shall -\n(a) promote, with special care, the educational and economic interests of backward classes or areas;\n(b) remove illiteracy and provide free and compulsory secondary education within minimum possible period;\n(c) make technical and professional education generally accessible and higher education equally accessible to all on the basis of merit;\n(d) ensure inexpensive and expeditious justice;\n(e) make provision for securing just and humane conditions of work, ensuring that children and women are not employed in vocations unsuited to their age or sex;\n(f) enable the people of different areas to participate in the Armed Forces; and\n(g) prevent prostitution, gambling and taking of injurious drugs.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '38', title: 'Promotion of social and economic well-being of the people', content: 'The State shall -\n(a) secure the well-being of the people, irrespective of sex, caste, creed or race, by raising their standard of living;\n(b) provide for all citizens, within the available resources of the country, facilities for work and adequate livelihood with reasonable rest and leisure;\n(c) provide for all persons employed in the service of Pakistan, social security by compulsory social insurance or other means;\n(d) provide basic necessities of life, such as food, clothing, housing, education and medical relief, for all citizens who are permanently or temporarily unable to earn their livelihood; and\n(e) reduce disparity in the income and earnings of individuals.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '39', title: 'Participation of people in Armed Forces', content: 'The State shall enable people from all parts of Pakistan to participate in the Armed Forces of Pakistan.', category: 'Fundamental' },
  { part: 'II', part_title: 'Fundamental Rights and Principles of Policy', chapter: '2', chapter_title: 'Principles of Policy', article: '40', title: 'Strengthening bonds with Muslim world', content: 'The State shall endeavor to preserve and strengthen fraternal relations among Muslim countries based on Islamic unity, support the common interests of the peoples of Asia, Africa and other Muslim countries, promote international peace and security, foster goodwill and friendly relations among all nations and encourage the settlement of international disputes by peaceful means.', category: 'Islamic' },

  // Part III: The Federation of Pakistan
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '1', chapter_title: 'The President', article: '41', title: 'The President', content: '(1) There shall be a President of Pakistan who shall be the Head of State and shall represent the unity of the Republic.\n(2) A person shall not be qualified for election as President unless he is a Muslim and has completed the age of forty-five years and is qualified to be elected as member of the National Assembly.\n(3) The President shall be elected by the members of an electoral college consisting of the members of the Senate, the National Assembly and the Provincial Assemblies.\n(4) The President shall hold office for a term of five years.\n(5) The President may, by writing under his hand addressed to the Speaker of the National Assembly, resign his office.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '1', chapter_title: 'The President', article: '42', title: 'Oath of the President', content: 'Before entering upon his office, the President shall make before the Chief Justice of Pakistan an oath in the form set out in the Third Schedule.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '1', chapter_title: 'The President', article: '43', title: 'Conditions of President\'s office', content: '(1) The President shall not hold any other office of profit in the service of Pakistan.\n(2) The President shall not be a candidate for election as a member of Majlis-e-Shoora (Parliament) or a Provincial Assembly.\n(3) The President shall not, while he holds office, be entitled to the emoluments and privileges of a member of Majlis-e-Shoora (Parliament).', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '1', chapter_title: 'The President', article: '44', title: 'Salary and privileges of the President', content: 'The President shall be entitled to such salary, allowances and privileges as may be determined by Act of Majlis-e-Shoora (Parliament) and, until so determined, such salary, allowances and privileges as are specified in the Second Schedule.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '1', chapter_title: 'The President', article: '45', title: 'Power of President to grant pardon, etc.', content: 'The President shall have power to grant pardon, reprieve and respite, and to remit, suspend or commute any sentence passed by any court, tribunal or other authority.', category: 'Criminal' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '1', chapter_title: 'The President', article: '46', title: 'President to be kept informed', content: 'The Prime Minister shall keep the President informed on all matters of internal and foreign policy and on all legislative proposals.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '1', chapter_title: 'The President', article: '47', title: 'Removal or impeachment of President', content: '(1) The President may, in accordance with the provisions of this Article, be removed from office on the ground of physical or mental incapacity or impeachment on a charge of violating the Constitution or gross misconduct.\n(2) The resolution for removal or impeachment shall be moved by not less than one-third of the total membership of the joint sitting of the Majlis-e-Shoora (Parliament).\n(3) If the resolution is passed by not less than two-thirds of the total membership, the President shall cease to hold office immediately.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '1', chapter_title: 'The President', article: '48', title: 'President to act on advice, etc.', content: '(1) In the exercise of his functions, the President shall act in accordance with the advice of the Cabinet or the Prime Minister.\n(2) The President may require the Cabinet or, as the case may be, the Prime Minister to reconsider such advice, and the President shall act in accordance with the advice tendered after such reconsideration.\n(3) The validity of any advice tendered by the Cabinet or the Prime Minister shall not be called in question in any court.', category: 'Constitutional' },

  // PM and Cabinet
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '2', chapter_title: 'The Majlis-e-Shoora (Parliament)', article: '50', title: 'Majlis-e-Shoora (Parliament)', content: 'There shall be a Majlis-e-Shoora (Parliament) of Pakistan consisting of the President and two Houses to be known respectively as the National Assembly and the Senate.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '2', chapter_title: 'The Majlis-e-Shoora (Parliament)', article: '51', title: 'National Assembly', content: '(1) The National Assembly shall consist of three hundred and thirty-six members, of which two hundred and sixty-six shall be elected directly by the people; sixty seats shall be reserved for women and ten seats for non-Muslims.\n(2) A person shall be entitled to vote if he is a citizen of Pakistan, not less than eighteen years of age, and registered as a voter.\n(3) The National Assembly shall be elected for a term of five years.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '2', chapter_title: 'The Majlis-e-Shoora (Parliament)', article: '52', title: 'Speaker and Deputy Speaker of National Assembly', content: 'After a general election, the National Assembly shall, at its first meeting and to the exclusion of any other business, elect from among its members a Speaker and a Deputy Speaker.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '2', chapter_title: 'The Majlis-e-Shoora (Parliament)', article: '58', title: 'Dissolution of National Assembly', content: '(1) The President shall dissolve the National Assembly if so advised by the Prime Minister, and the National Assembly shall, unless sooner dissolved, stand dissolved at the expiration of five years from the date of its first meeting.\n(2) The President may also dissolve the National Assembly in his discretion where, in his opinion, a situation has arisen in which the Government of the Federation cannot be carried on in accordance with the provisions of the Constitution and an appeal to the electorate is necessary.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '2', chapter_title: 'The Majlis-e-Shoora (Parliament)', article: '59', title: 'The Senate', content: '(1) The Senate shall consist of ninety-six members.\n(2) The members of the Senate shall be elected by the members of the Provincial Assemblies and the members of the National Assembly.\n(3) The Senate shall not be subject to dissolution but the term of its members shall be six years.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '2', chapter_title: 'The Majlis-e-Shoora (Parliament)', article: '62', title: 'Qualifications for membership of Majlis-e-Shoora (Parliament)', content: '(1) A person shall not be qualified to be elected or chosen as a member of Majlis-e-Shoora (Parliament) unless -\n(a) he is a citizen of Pakistan;\n(b) he is, in the case of the National Assembly, not less than twenty-five years of age and, in the case of the Senate, not less than thirty years of age;\n(c) he is of good character and is not commonly known as one who violates Islamic injunctions;\n(d) he has adequate knowledge of Islamic teachings and practices obligatory duties prescribed by Islam as well as abstains from major sins;\n(e) he is sagacious, righteous and non-profligate and honest and ameen;\n(f) he has not, after the establishment of Pakistan, worked against the integrity of the country or opposed the ideology of Pakistan.\n(2) The disqualifications specified in paragraphs (c), (d) and (e) shall not be called in question except before the Supreme Court.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '2', chapter_title: 'The Majlis-e-Shoora (Parliament)', article: '63', title: 'Disqualifications for membership of Majlis-e-Shoora (Parliament)', content: '(1) A person shall be disqualified from being elected or chosen as, or from being, a member of the Majlis-e-Shoora (Parliament) if -\n(a) he is of unsound mind;\n(b) he is an undischarged insolvent;\n(c) he ceases to be a citizen of Pakistan;\n(d) he holds an office of profit in the service of Pakistan;\n(e) he is convicted of an offence involving moral turpitude;\n(f) he has been convicted for propagating hatred between groups;\n(g) he has been convicted for an offence under the Election Laws;\n(h) he has been convicted of an offence under the Prevention of Corruption Act;\n(i) he has been dismissed from the service of Pakistan on grounds of misconduct;\n(j) he has been removed from a judicial office;\n(k) he is a member of a Legislature of a foreign country;\n(l) he is a foreign national.\n(2) If any question arises whether a member of Majlis-e-Shoora (Parliament) has become disqualified, the Speaker or Chairman shall refer the question to the Chief Election Commissioner.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '3', chapter_title: 'The Federal Government', article: '90', title: 'The Federal Government', content: '(1) The Federal Government shall consist of the Prime Minister and the Federal Ministers.\n(2) The Prime Minister shall be appointed by the President from among the members of the National Assembly.\n(3) The President shall, in the exercise of his functions, act on and in accordance with the advice of the Cabinet.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '3', chapter_title: 'The Federal Government', article: '91', title: 'The Prime Minister', content: '(1) The President shall appoint a Prime Minister who, in his opinion, is most likely to command the confidence of the majority of the members of the National Assembly.\n(2) The Prime Minister shall, before entering upon his office, make before the President an oath in the form set out in the Third Schedule.\n(3) The Cabinet shall be collectively responsible to the National Assembly.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '3', chapter_title: 'The Federal Government', article: '92', title: 'Federal Ministers', content: '(1) The President shall appoint Federal Ministers on the advice of the Prime Minister.\n(2) No person shall be appointed as a Federal Minister unless he is a member of the National Assembly.\n(3) The Federal Ministers shall hold office during the pleasure of the Prime Minister.', category: 'Constitutional' },
  { part: 'III', part_title: 'The Federation of Pakistan', chapter: '3', chapter_title: 'The Federal Government', article: '93', title: 'Advisers', content: 'The Prime Minister may appoint, from amongst persons who are not members of the National Assembly, such number of Advisers as he considers necessary.', category: 'Constitutional' },

  // Part IV: Provinces
  { part: 'IV', part_title: 'Provinces', chapter: '1', chapter_title: 'The Governors', article: '101', title: 'Governors of Provinces', content: '(1) There shall be a Governor for each Province who shall be appointed by the President on the advice of the Prime Minister.\n(2) A person shall not be qualified for appointment as Governor unless he is qualified to be elected as member of the National Assembly and has completed the age of forty-five years.\n(3) The Governor shall hold office during the pleasure of the President and shall be entitled to such salary, allowances and privileges as the President may determine.', category: 'Constitutional' },
  { part: 'IV', part_title: 'Provinces', chapter: '2', chapter_title: 'Provincial Assemblies', article: '106', title: 'Constitution of Provincial Assemblies', content: '(1) Each Provincial Assembly shall consist of members elected directly by the people of the Province.\n(2) Seats shall be reserved for women and non-Muslims in each Provincial Assembly.\n(3) The Provincial Assembly shall be elected for a term of five years.', category: 'Constitutional' },
  { part: 'IV', part_title: 'Provinces', chapter: '3', chapter_title: 'The Provincial Governments', article: '129', title: 'The Provincial Government', content: '(1) The Provincial Government shall consist of the Chief Minister and the Provincial Ministers.\n(2) The Chief Minister shall be appointed by the Governor from among the members of the Provincial Assembly.\n(3) The Provincial Cabinet shall be collectively responsible to the Provincial Assembly.', category: 'Constitutional' },
  { part: 'IV', part_title: 'Provinces', chapter: '3', chapter_title: 'The Provincial Governments', article: '130', title: 'The Chief Minister', content: '(1) The Governor shall appoint a Chief Minister who, in his opinion, is most likely to command the confidence of the majority of the members of the Provincial Assembly.\n(2) The Chief Minister shall hold office during the pleasure of the Governor, but the Governor shall not exercise his powers under this clause unless he is satisfied that the Chief Minister does not command the confidence of the majority of the members of the Provincial Assembly.', category: 'Constitutional' },
  { part: 'IV', part_title: 'Provinces', chapter: '3', chapter_title: 'The Provincial Governments', article: '131', title: 'Provincial Ministers', content: '(1) The Governor shall appoint Provincial Ministers on the advice of the Chief Minister.\n(2) No person shall be appointed as a Provincial Minister unless he is a member of the Provincial Assembly.\n(3) The Provincial Ministers shall hold office during the pleasure of the Chief Minister.', category: 'Constitutional' },

  // Part V: Relations between Federation and Provinces
  { part: 'V', part_title: 'Relations between Federation and Provinces', chapter: '1', chapter_title: 'Distribution of Legislative Powers', article: '141', title: 'Extent of Federal and Provincial laws', content: 'Subject to the Constitution, Majlis-e-Shoora (Parliament) may make laws for the whole or any part of Pakistan, and a Provincial Assembly may make laws for the Province or any part thereof.', category: 'Constitutional' },
  { part: 'V', part_title: 'Relations between Federation and Provinces', chapter: '1', chapter_title: 'Distribution of Legislative Powers', article: '142', title: 'Subject matters of Federal and Provincial laws', content: '(1) Majlis-e-Shoora (Parliament) shall have exclusive power to make laws with respect to any matter in the Federal Legislative List.\n(2) A Provincial Assembly shall have exclusive power to make laws with respect to any matter in the Provincial Legislative List.\n(3) Both Parliament and a Provincial Assembly shall have power to make laws with respect to any matter in the Concurrent Legislative List.', category: 'Constitutional' },
  { part: 'V', part_title: 'Relations between Federation and Provinces', chapter: '1', chapter_title: 'Distribution of Legislative Powers', article: '143', title: 'Residual powers', content: 'Majlis-e-Shoora (Parliament) shall have exclusive power to make laws with respect to any matter not enumerated in either the Federal Legislative List or the Provincial Legislative List.', category: 'Constitutional' },
  { part: 'V', part_title: 'Relations between Federation and Provinces', chapter: '1', chapter_title: 'Distribution of Legislative Powers', article: '144', title: 'Repugnancy of laws', content: 'If any provision of an Act of a Provincial Assembly is repugnant to any provision of an Act of Majlis-e-Shoora (Parliament) which Parliament is competent to enact, the Act of Parliament shall prevail and the Act of the Provincial Assembly shall, to the extent of the repugnancy, be void.', category: 'Constitutional' },

  // Part VI: Finance, Property, Contracts and Suits
  { part: 'VI', part_title: 'Finance, Property, Contracts and Suits', chapter: '1', chapter_title: 'Finance', article: '160', title: 'National Finance Commission', content: '(1) Within six months of the commencing day and thereafter at intervals not exceeding five years, the President shall constitute a National Finance Commission consisting of the Federal Minister for Finance, the Provincial Ministers for Finance, and such other persons as may be appointed.\n(2) The Commission shall make recommendations to the President as to the distribution of revenues between the Federation and the Provinces.\n(3) The recommendations of the Commission shall be binding on the President.', category: 'Corporate' },
  { part: 'VI', part_title: 'Finance, Property, Contracts and Suits', chapter: '1', chapter_title: 'Finance', article: '161', title: 'Natural gas and hydro-electric power', content: '(1) The net proceeds of the Federal duty of excise on natural gas and the proceeds of the Federal tax on the sale of natural gas shall stand transferred to the Province in which the gas is produced.\n(2) The net proceeds of the Federal tax on the generation of hydro-electric power shall stand transferred to the Province in which the power is generated.', category: 'Property' },

  // Part VII: The Judicature
  { part: 'VII', part_title: 'The Judicature', chapter: '1', chapter_title: 'The Supreme Court of Pakistan', article: '175', title: 'Establishment and jurisdiction of courts', content: '(1) There shall be a Supreme Court of Pakistan, a High Court for each Province and such other courts as may be established by law.\n(2) No court shall have any jurisdiction save as is or may be conferred on it by the Constitution or by or under any law.\n(3) The Judiciary shall be separated progressively from the Executive within fourteen years from the commencing day.', category: 'Constitutional' },
  { part: 'VII', part_title: 'The Judicature', chapter: '1', chapter_title: 'The Supreme Court of Pakistan', article: '176', title: 'Constitution of Supreme Court', content: 'The Supreme Court shall consist of a Chief Justice to be known as the Chief Justice of Pakistan and so many other Judges as may be determined by Act of Majlis-e-Shoora (Parliament) or, until so determined, as may be fixed by the President.', category: 'Constitutional' },
  { part: 'VII', part_title: 'The Judicature', chapter: '1', chapter_title: 'The Supreme Court of Pakistan', article: '177', title: 'Appointment of Supreme Court Judges', content: '(1) The Chief Justice of Pakistan shall be appointed by the President on the advice of the Prime Minister.\n(2) A person shall not be appointed as a Judge of the Supreme Court unless he has been a Judge of a High Court for five years or has been an advocate of a High Court for fifteen years.', category: 'Constitutional' },
  { part: 'VII', part_title: 'The Judicature', chapter: '1', chapter_title: 'The Supreme Court of Pakistan', article: '184', title: 'Original jurisdiction of the Supreme Court', content: '(1) The Supreme Court shall, to the exclusion of any other court, have original jurisdiction in any dispute between the Federal Government and a Provincial Government or between Provincial Governments.\n(2) The Supreme Court may, if it considers that a question of public importance with reference to the enforcement of any of the Fundamental Rights conferred by Chapter I of Part II is involved, have the power to make an order of the nature mentioned in Article 199.\n(3) The Supreme Court shall have such other jurisdiction as may be conferred on it by or under any law.', category: 'Constitutional' },
  { part: 'VII', part_title: 'The Judicature', chapter: '1', chapter_title: 'The Supreme Court of Pakistan', article: '185', title: 'Appellate jurisdiction of the Supreme Court', content: '(1) The Supreme Court shall have jurisdiction to hear and determine appeals from judgments, decrees, orders or sentences of a High Court.\n(2) An appeal shall lie to the Supreme Court from any judgment, decree, order or sentence of a High Court in cases involving a substantial question of law as to the interpretation of the Constitution.\n(3) An appeal shall lie to the Supreme Court from any judgment, decree, order or sentence of a High Court in such cases as may be prescribed by law.', category: 'Constitutional' },
  { part: 'VII', part_title: 'The Judicature', chapter: '1', chapter_title: 'The Supreme Court of Pakistan', article: '186', title: 'Advisory jurisdiction of the Supreme Court', content: 'If, at any time, the President considers that a question of law of public importance has arisen, he may refer the question to the Supreme Court for its opinion.', category: 'Constitutional' },
  { part: 'VII', part_title: 'The Judicature', chapter: '1', chapter_title: 'The Supreme Court of Pakistan', article: '187', title: 'Power of Supreme Court to make rules', content: 'The Supreme Court may, with the approval of the President, make rules for regulating the practice and procedure of the Court.', category: 'Constitutional' },
  { part: 'VII', part_title: 'The Judicature', chapter: '1', chapter_title: 'The Supreme Court of Pakistan', article: '188', title: 'Review of judgments by the Supreme Court', content: 'The Supreme Court shall have the power, subject to the provisions of any Act of Majlis-e-Shoora (Parliament) and of any rules made by the Supreme Court, to review any judgment pronounced or order made by it.', category: 'Constitutional' },
  { part: 'VII', part_title: 'The Judicature', chapter: '2', chapter_title: 'The High Courts', article: '192', title: 'Constitution of High Courts', content: 'There shall be a High Court for each Province consisting of a Chief Justice and so many other Judges as may be determined by law.', category: 'Constitutional' },
  { part: 'VII', part_title: 'The Judicature', chapter: '2', chapter_title: 'The High Courts', article: '193', title: 'Appointment of High Court Judges', content: '(1) A Judge of a High Court shall be appointed by the President on the advice of the Prime Minister.\n(2) A person shall not be appointed as a Judge of a High Court unless he has been an advocate of a High Court for ten years or has held a judicial office in Pakistan for ten years.', category: 'Constitutional' },
  { part: 'VII', part_title: 'The Judicature', chapter: '2', chapter_title: 'The High Courts', article: '199', title: 'Jurisdiction of High Court', content: '(1) Subject to the Constitution, a High Court may, if it is satisfied that no other adequate remedy is provided by law -\n(a) on the application of any aggrieved person, make an order directing a person performing functions in connection with the affairs of the Federation, a Province or a local authority to refrain from doing any particular act;\n(b) on the application of any person, make an order requiring a person holding or purporting to hold a public office to show under what authority he claims to hold that office;\n(c) on the application of any aggrieved person, make an order giving such directions to a person or authority as may be appropriate for the enforcement of any of the Fundamental Rights.\n(2) The power conferred by this Article shall not extend to matters relating to the Armed Forces or to any law relating to preventive detention.', category: 'Constitutional' },
  { part: 'VII', part_title: 'The Judicature', chapter: '3', chapter_title: 'Federal Shariat Court', article: '203C', title: 'The Federal Shariat Court', content: '(1) There shall be constituted a court to be called the Federal Shariat Court.\n(2) The Federal Shariat Court shall consist of not more than eight Muslim Judges, including a Chief Justice.\n(3) The Chief Justice shall be a person who is, or has been, a Judge of the Supreme Court or who is, or has been, qualified to be a Judge of the Supreme Court.\n(4) The Court shall have jurisdiction to examine any law with respect to its conformity with the injunctions of Islam.', category: 'Islamic' },
  { part: 'VII', part_title: 'The Judicature', chapter: '3A', chapter_title: 'Supreme Judicial Council', article: '209', title: 'Supreme Judicial Council', content: '(1) There shall be a Supreme Judicial Council of Pakistan.\n(2) The Council shall consist of the Chief Justice of Pakistan, the two next most senior Judges of the Supreme Court, and the Chief Justices of the High Courts.\n(3) The Council shall review the conduct of Judges and may recommend their removal to the President.', category: 'Constitutional' },

  // Part VIII: Elections
  { part: 'VIII', part_title: 'Elections', chapter: '', chapter_title: '', article: '213', title: 'Chief Election Commissioner', content: '(1) There shall be a Chief Election Commissioner who shall be appointed by the President on the advice of the Prime Minister.\n(2) The Chief Election Commissioner shall have such powers and functions as are conferred on him by the Constitution and law.\n(3) The Chief Election Commissioner shall hold office for a term of five years.', category: 'Constitutional' },
  { part: 'VIII', part_title: 'Elections', chapter: '', chapter_title: '', article: '218', title: 'Election Commission', content: '(1) The Election Commission shall consist of the Chief Election Commissioner and four members.\n(2) It shall be the duty of the Election Commission to organize and conduct elections and to make such arrangements as are necessary to ensure that the election is conducted honestly, justly, fairly and in accordance with law.', category: 'Constitutional' },
  { part: 'VIII', part_title: 'Elections', chapter: '', chapter_title: '', article: '222', title: 'Electoral laws', content: 'Subject to the Constitution, Majlis-e-Shoora (Parliament) may by law provide for the conduct of elections and all matters connected therewith.', category: 'Constitutional' },
  { part: 'VIII', part_title: 'Elections', chapter: '', chapter_title: '', article: '224', title: 'Time of elections', content: '(1) A general election to the National Assembly shall be held within sixty days immediately following the day on which the term of the Assembly expires.\n(2) A general election to a Provincial Assembly shall be held within sixty days immediately following the day on which the term of the Assembly expires.', category: 'Constitutional' },

  // Part IX: Islamic Provisions
  { part: 'IX', part_title: 'Islamic Provisions', chapter: '', chapter_title: '', article: '227', title: 'Provisions relating to the Holy Quran and Sunnah', content: '(1) All existing laws shall be brought in conformity with the injunctions of Islam as laid down in the Holy Quran and Sunnah, and no law shall be enacted which is repugnant to such injunctions.\n(2) Nothing in this Article shall affect the personal laws of non-Muslim citizens or their status as citizens.', category: 'Islamic' },
  { part: 'IX', part_title: 'Islamic Provisions', chapter: '', chapter_title: '', article: '228', title: 'Council of Islamic Ideology', content: '(1) There shall be a Council of Islamic Ideology consisting of such members as may be appointed by the President.\n(2) The Council shall make recommendations to the Federal Government and the Provincial Governments as to the means of enabling Muslims to order their lives in accordance with the principles of Islam.\n(3) The Council shall examine all laws and determine whether they are repugnant to the injunctions of Islam.', category: 'Islamic' },
  { part: 'IX', part_title: 'Islamic Provisions', chapter: '', chapter_title: '', article: '229', title: 'References to Council of Islamic Ideology', content: 'The President, the Governor of a Province, the Speaker of the National Assembly or the Chairman of the Senate may, if he considers that a proposed law is repugnant to the injunctions of Islam, refer the same to the Council of Islamic Ideology.', category: 'Islamic' },
  { part: 'IX', part_title: 'Islamic Provisions', chapter: '', chapter_title: '', article: '230', title: 'Functions of the Council of Islamic Ideology', content: 'The functions of the Council of Islamic Ideology shall be -\n(a) to make recommendations to the Federal Government and the Provincial Governments as to the means of enabling and encouraging the Muslims to order their lives in accordance with the principles of Islam;\n(b) to examine all laws in force immediately before the commencing day with a view to bringing them into conformity with the injunctions of Islam.', category: 'Islamic' },

  // Part X: Emergency Provisions
  { part: 'X', part_title: 'Emergency Provisions', chapter: '', chapter_title: '', article: '232', title: 'Proclamation of emergency on account of war, etc.', content: '(1) If the President is satisfied that a grave emergency exists in which Pakistan is threatened by war or external aggression, or by internal disturbance beyond the power of a Provincial Government to control, he may issue a Proclamation of Emergency.\n(2) A Proclamation of Emergency shall be laid before the National Assembly and shall cease to be in force at the expiration of two months unless approved by a resolution of the National Assembly.\n(3) While a Proclamation of Emergency is in force, the Federal Government may give directions to any Provincial Government as to the manner in which its executive authority is to be exercised.', category: 'Constitutional' },
  { part: 'X', part_title: 'Emergency Provisions', chapter: '', chapter_title: '', article: '233', title: 'Power to suspend Fundamental Rights during emergency', content: '(1) While a Proclamation of Emergency is in force, the President may, by Order, declare that the right to move any court for the enforcement of such of the Fundamental Rights conferred by Chapter I of Part II as may be specified in the Order shall remain suspended.\n(2) Every Order made under this Article shall be laid before the National Assembly within fifteen days.', category: 'Fundamental' },
  { part: 'X', part_title: 'Emergency Provisions', chapter: '', chapter_title: '', article: '234', title: 'Power to issue Proclamation in case of failure of constitutional machinery in a Province', content: 'If the President, on receipt of a report from the Governor of a Province, is satisfied that a situation has arisen in which the Government of the Province cannot be carried on in accordance with the provisions of the Constitution, the President may issue a Proclamation assuming to himself the functions of the Government of the Province.', category: 'Constitutional' },
  { part: 'X', part_title: 'Emergency Provisions', chapter: '', chapter_title: '', article: '235', title: 'Proclamation in case of financial emergency', content: 'If the President is satisfied that the financial stability or credit of Pakistan is threatened, he may issue a Proclamation of Financial Emergency.', category: 'Corporate' },
  { part: 'X', part_title: 'Emergency Provisions', chapter: '', chapter_title: '', article: '236', title: 'Revocation of Proclamation', content: 'A Proclamation issued under this Part may be revoked by a subsequent Proclamation.', category: 'Constitutional' },
  { part: 'X', part_title: 'Emergency Provisions', chapter: '', chapter_title: '', article: '237', title: 'Bar to challenge Proclamation', content: 'Neither the validity of a Proclamation issued under this Part nor the validity of any Order made under Article 233 shall be called in question in any court.', category: 'Constitutional' },

  // Part XI: Amendment of Constitution
  { part: 'XI', part_title: 'Amendment of Constitution', chapter: '', chapter_title: '', article: '238', title: 'Amendment of Constitution', content: 'Subject to the provisions of this Part, the Constitution may be amended by an Act of Majlis-e-Shoora (Parliament).', category: 'Constitutional' },
  { part: 'XI', part_title: 'Amendment of Constitution', chapter: '', chapter_title: '', article: '239', title: 'Procedure for amendment', content: '(1) A Bill to amend the Constitution may originate in either House of Majlis-e-Shoora (Parliament).\n(2) When the Bill is passed by each House by a majority of not less than two-thirds of its total membership, it shall be presented to the President for assent.\n(3) The President shall assent to the Bill within thirty days.\n(4) An amendment of the Constitution shall not be called in question in any court on any ground.\n(5) The provisions of this Article shall not be applicable to a Bill to amend the Constitution which would alter the boundaries of a Province.', category: 'Constitutional' },

  // Part XII: Miscellaneous
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '240', title: 'Services of Pakistan', content: 'Subject to the Constitution, the appointments of persons to be, and the terms and conditions of service of persons in, the service of Pakistan shall be determined by or under Act of Majlis-e-Shoora (Parliament).', category: 'Service' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '241', title: 'Public Service Commission', content: 'The Federal Public Service Commission and a Provincial Public Service Commission shall be constituted by the President and the Governor of each Province, respectively.', category: 'Service' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '242', title: 'Terms and conditions of service of Public Service Commission members', content: 'The members of the Federal Public Service Commission and of the Provincial Public Service Commissions shall be appointed for a term of five years.', category: 'Service' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '243', title: 'The Armed Forces', content: '(1) The Federal Government shall have the power to raise and maintain the Armed Forces of Pakistan.\n(2) The Supreme Command of the Armed Forces shall vest in the President.\n(3) The President shall not exercise his powers in relation to the command of the Armed Forces except on the advice of the Prime Minister.\n(4) The Chief of the Army Staff, the Chief of the Naval Staff and the Chief of the Air Staff shall be appointed by the President on the advice of the Prime Minister.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '244', title: 'Oath of Armed Forces members', content: 'Every member of the Armed Forces shall make an oath in the form set out in the Third Schedule.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '245', title: 'Functions of the Armed Forces', content: '(1) The Armed Forces shall, under the directions of the Federal Government, defend Pakistan against external aggression or threat of war, and, when called upon to do so, act in aid of civil power.\n(2) The validity of any direction issued by the Federal Government under this Article shall not be called in question in any court.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '246', title: 'Federal Legislative List', content: 'The Federal Legislative List consists of matters over which Majlis-e-Shoora (Parliament) has exclusive power to make laws, including defence, foreign affairs, currency, inter-provincial coordination, and such other matters as are specified in the List.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '247', title: 'Provincial Legislative List', content: 'The Provincial Legislative List consists of matters over which a Provincial Assembly has exclusive power to make laws, including local government, public order, agriculture, and such other matters as are specified in the List.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '248', title: 'Concurrent Legislative List', content: 'The Concurrent Legislative List consists of matters over which both Parliament and Provincial Assemblies have power to make laws, including criminal law, family law, evidence, and such other matters as are specified in the List.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '249', title: 'Laws to continue in force', content: 'Subject to the Constitution, all laws in force immediately before the commencing day shall, so far as applicable, continue in force until altered, repealed or amended by the appropriate legislature.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '250', title: 'Courts to continue', content: 'All courts existing immediately before the commencing day shall continue to function until new courts are established.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '251', title: 'National language', content: '(1) The National language of Pakistan is Urdu, and arrangements shall be made for its being used for official and other purposes within fifteen years from the commencing day.\n(2) English may be used for official purposes until arrangements are made for its replacement by Urdu.\n(3) Provincial languages may be used for official purposes in the respective Provinces.', category: 'Fundamental' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '252', title: 'Power to impose taxes', content: 'No tax shall be levied except by or under the authority of an Act of Majlis-e-Shoora (Parliament) or a Provincial Assembly.', category: 'Corporate' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '253', title: 'Protection to the President and Governors', content: 'The President and the Governors shall not be answerable to any court for the exercise of their powers.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '254', title: 'Protection of publication of proceedings', content: 'No publication of any proceedings of Majlis-e-Shoora (Parliament) or a Provincial Assembly shall be deemed to be a contempt of court.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '255', title: 'Immunity from legal proceedings', content: 'No member of Majlis-e-Shoora (Parliament) or a Provincial Assembly shall be liable to any proceedings in any court in respect of anything said or any vote given by him in the Assembly.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '256', title: 'Private property of State not liable to attachment', content: 'The private property of the State shall not be liable to attachment or sale in execution of any decree or order of a court.', category: 'Property' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '257', title: 'Power of Government to enter into contracts', content: 'The executive authority of the Federation and of a Province shall extend to the making of contracts on behalf of the Federation or the Province.', category: 'Corporate' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '258', title: 'Suits and proceedings', content: 'The Federation may sue or be sued by the name of Pakistan and a Province may sue or be sued by the name of the Province.', category: 'Corporate' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '259', title: 'Removal of difficulties', content: 'If any difficulty arises in giving effect to any provision of the Constitution, the President may make such Order as appears to him necessary for the purpose of removing the difficulty.', category: 'Constitutional' },
  { part: 'XII', part_title: 'Miscellaneous', chapter: '', chapter_title: '', article: '260', title: 'Definitions', content: 'In the Constitution, unless the context otherwise requires, the following expressions have the meanings hereby respectively assigned to them:\n"Act" means an Act of Majlis-e-Shoora (Parliament) or a Provincial Assembly;\n"Article" means an Article of the Constitution;\n"citizen" means a citizen of Pakistan;\n"corporation" includes any statutory corporation;\n"court" means any court of competent jurisdiction;\n"High Court" includes the Supreme Court of Pakistan;\n"law" includes any ordinance, order, rule, regulation, by-law, notification, and any other legal instrument;\n"property" includes any right, title or interest in property.', category: 'Constitutional' },
];

export async function seedConstitution(adapter) {
  const existing = await adapter.queryOne('SELECT COUNT(*) as c FROM constitution');
  if (Number(existing?.c || 0) > 10) return { message: 'Already seeded', count: existing.c };
  let inserted = 0;
  for (const art of CONSTITUTION_ARTICLES) {
    try {
      await adapter.run(
        `INSERT INTO constitution (id, part, part_title, chapter, chapter_title, article, title, content, category)
         VALUES (gen_random_uuid(),?,?,?,?,?,?,?,?)`,
        [art.part, art.part_title, art.chapter, art.chapter_title, art.article, art.title, art.content, art.category]
      );
      inserted++;
    } catch (e) {
      console.warn(`Skipping Article ${art.article}: ${e.message}`);
    }
  }
  return { message: `${inserted} constitution articles seeded`, count: inserted };
}
